<template><div class="page-card"><div class="toolbar"><el-button v-permission="'ADMIN'" type="primary" @click="open()">新增产线</el-button></div>
<el-table :data="rows" border><el-table-column prop="lineCode" label="产线编号" width="180"/><el-table-column prop="lineName" label="产线名称" min-width="180"/><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status===1?'success':'info'">{{row.status===1?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column v-if="user.isAdmin" label="操作" width="100"><template #default="{row}"><el-button link type="primary" @click="open(row)">编辑</el-button></template></el-table-column></el-table>
<el-dialog v-model="visible" :title="form.id?'编辑产线':'新增产线'" width="420px"><el-form label-width="90px"><el-form-item label="产线编号"><el-input v-model="form.lineCode"/></el-form-item><el-form-item label="产线名称"><el-input v-model="form.lineName"/></el-form-item><el-form-item label="状态"><el-switch v-model="form.status" :active-value="1" :inactive-value="0"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup>import{ref,reactive,onMounted}from'vue';import{ElMessage}from'element-plus';import{getProductionLines,saveProductionLine}from'../api';import{useUserStore}from'../store/user';const user=useUserStore(),rows=ref([]),visible=ref(false),form=reactive({id:null,lineCode:'',lineName:'',status:1});async function load(){rows.value=await getProductionLines(false)}function open(row){Object.assign(form,row||{id:null,lineCode:'',lineName:'',status:1});visible.value=true}async function save(){if(!form.lineCode){ElMessage.warning('产线编号不能为空');return}await saveProductionLine({...form});visible.value=false;ElMessage.success('保存成功');load()}onMounted(load)</script>
